import csv
import gzip
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, "rb") as handle:
        raw = handle.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    text = raw.decode("utf-8-sig")
    return text


def read_lines(path):
    return [line for line in read_text(path).splitlines() if line.strip()]


def list_files(directory):
    found = []
    if os.path.isdir(directory):
        for root, _dirs, files in os.walk(directory):
            for name in files:
                found.append(os.path.join(root, name))
    return sorted(found)


def local_to_epoch(naive, zone, fold):
    return int(naive.replace(tzinfo=zone, fold=fold).timestamp())


def norm_dir(value):
    value = value.strip().upper()
    if value in ("IN", "I", "K", "CLOCK_IN"):
        return "IN"
    if value in ("OUT", "O", "G", "CLOCK_OUT"):
        return "OUT"
    return None


def parse_abbr(path, zone):
    punches = []
    header = None
    for row in csv.reader(io.StringIO(read_text(path))):
        if not row or not any(cell.strip() for cell in row):
            continue
        cells = [cell.strip() for cell in row]
        if "Badge" in cells and "Punch" in cells:
            header = cells
            continue
        if header is None:
            continue
        rec = dict(zip(header, cells))
        stamp = rec["Time"].upper()
        meridiem = None
        if stamp.endswith("AM") or stamp.endswith("PM"):
            meridiem = stamp[-2:]
            stamp = stamp[:-2].strip()
        hour, minute, second = [int(part) for part in stamp.split(":")]
        if meridiem:
            hour = hour % 12 + (12 if meridiem == "PM" else 0)
        month, day, year = [int(part) for part in rec["Date"].split("/")]
        naive = datetime(year, month, day, hour, minute, second)
        fold = 0 if rec["Zone"].upper().endswith("DT") else 1
        punches.append((rec["Record"], rec["Badge"], norm_dir(rec["Punch"]),
                        local_to_epoch(naive, zone, fold)))
    return punches


def to_int_seconds(value):
    return int(value // 1)


def parse_epoch(path):
    punches = []
    schema = 1
    for line in read_lines(path):
        obj = json.loads(line)
        if "schema" in obj and "id" not in obj and "punch_id" not in obj:
            schema = int(obj["schema"])
            continue
        if obj.get("heartbeat"):
            continue
        if schema == 2:
            punches.append((str(obj["punch_id"]), obj["employee"], norm_dir(obj["direction"]),
                            to_int_seconds(obj["epoch_ms"] / 1000 if not isinstance(obj["epoch_ms"], int)
                                           else Fraction(obj["epoch_ms"], 1000))))
        else:
            if "ts_ms" in obj:
                value = obj["ts_ms"]
                seconds = to_int_seconds(value / 1000 if not isinstance(value, int) else Fraction(value, 1000))
            else:
                seconds = to_int_seconds(obj["ts"])
            punches.append((str(obj["id"]), obj["emp"], norm_dir(obj["dir"]), seconds))
    return punches


def parse_offset(path):
    punches = []
    text = read_text(path)
    for rec in csv.DictReader(io.StringIO(text), delimiter=";"):
        if not rec.get("punch_id"):
            continue
        moment = datetime.fromisoformat(rec["timestamp"].strip())
        punches.append((rec["punch_id"], rec["employee"], norm_dir(rec["event"]),
                        int(moment.timestamp())))
    return punches


def parse_legacy(path, zone):
    punches = []
    offset = None
    for line in read_lines(path):
        kind = line[0]
        if kind == "H":
            tail = line[13:18].strip()
            offset = None
            if tail:
                sign = -1 if tail[0] == "-" else 1
                offset = sign * (int(tail[1:3]) * 3600 + int(tail[3:5]) * 60)
        elif kind == "D":
            stamp = line[16:30]
            naive = datetime(int(stamp[0:4]), int(stamp[4:6]), int(stamp[6:8]),
                             int(stamp[8:10]), int(stamp[10:12]), int(stamp[12:14]))
            if offset is None:
                probe = naive.replace(tzinfo=zone, fold=0)
                used = probe.utcoffset() - probe.dst()
                used = int(used.total_seconds())
                noon = naive.replace(hour=12, minute=0, second=0, tzinfo=zone)
                used = int((noon.utcoffset() - noon.dst()).total_seconds())
            else:
                used = offset
            epoch = int((naive - datetime(1970, 1, 1)).total_seconds()) - used
            badge = "E" + line[9:15].strip()
            punches.append((line[1:9], badge, norm_dir(line[15]), epoch))
    return punches


def parse_de(path, zone):
