    header = None
    for line in read_lines(path):
        cells = [cell.strip() for cell in line.split("\t")]
        if "Ausweis" in cells:
            header = cells
            continue
        if header is None:
            continue
        rec = dict(zip(header, cells))
        day, month, year = [int(part) for part in rec["Datum"].split(".")]
        parts = rec["Uhrzeit"].split(":")
        naive = datetime(year, month, day, int(parts[0]), int(parts[1]),
                         int(parts[2]) if len(parts) > 2 else 0)
        fold = 0 if rec["Zeitzone"].upper() == "MESZ" else 1
        punches.append((rec["Nr"], rec["Ausweis"], norm_dir(rec["Buchung"]),
                        local_to_epoch(naive, zone, fold)))
    return punches


def parse_local_csv(path, zone):
