        obj = json.loads(line)
        punch = obj.get("punch")
        if not punch:
            continue
        naive = datetime.strptime(punch["at"].strip(), "%Y-%m-%d %H:%M:%S")
        ident = punch["id"]
        ident = str(int(ident)) if isinstance(ident, (int, float)) else str(ident)
        punches.append((ident, punch["badge"], norm_dir(punch["type"]),
                        local_to_epoch(naive, zone, 0)))
    return punches


