        return parse_abbr(path, zone)
    if fmt == "epoch-jsonl":
        return parse_epoch(path)
    if fmt == "offset-csv":
        return parse_offset(path)
    if fmt == "legacy-fixed":
        return parse_legacy(path, zone)
    if fmt == "de-tsv":
        return parse_de(path, zone)
    if fmt == "local-csv":
        return parse_local_csv(path, zone)
    if fmt == "local-jsonl":
        return parse_local_jsonl(path, zone)
    raise ValueError("unknown format " + fmt)


def read_csv(path):
    return list(csv.DictReader(io.StringIO(read_text(path))))


def parse_utc(text):
    text = text.strip()
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    moment = datetime.fromisoformat(text)
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=UTC)
    return moment


def round_cents(value):
    return int((value * 100 + Fraction(1, 2)) // 1)


def main():
    in_dir, out_file = sys.argv[1], sys.argv[2]
    period = json.loads(read_text(os.path.join(in_dir, "period.json")))
    start = date.fromisoformat(period["start"])
    end = date.fromisoformat(period["end"])
    cutoff = parse_utc(period["corrections_cutoff"])

