    corrections.sort(key=lambda item: (item[0], item[1]))
    applied = 0
    for _issued, _cid, row in corrections:
        key = (row["site"].strip(), row["punch_id"].strip())
        action = row["action"].strip()
        if action == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches:
                punches[key][2] = int(parse_utc(row["time"]).timestamp())
                applied += 1
        elif action == "add":
            if key not in existed:
                existed.add(key)
                punches[key] = [row["employee"].strip(), norm_dir(row["type"]),
                                int(parse_utc(row["time"]).timestamp())]
                applied += 1

    by_employee = {}
    for (site, ident), (badge, direction, epoch) in punches.items():
        if badge in employees:
            by_employee.setdefault(badge, []).append((epoch, 0 if direction == "OUT" else 1, site, ident, direction))

    def shift_epoch(site, epoch):
        zone = sites[site][0]
        offset = int(datetime.fromtimestamp(epoch, zone).utcoffset().total_seconds())
        rem = (epoch + offset) % 360
        return epoch + (360 - rem if rem >= 180 else -rem)

    def workday(site_home, epoch):
        return datetime.fromtimestamp(epoch, sites[site_home][0]).date()

    def night_seconds(site, begin, finish):
        zone = sites[site][0]
        first = datetime.fromtimestamp(begin, zone).date() - timedelta(days=1)
        last = datetime.fromtimestamp(finish, zone).date()
        total = 0
        day = first
        while day <= last:
            lo = local_to_epoch(datetime(day.year, day.month, day.day, 22), zone, 0)
            nxt = day + timedelta(days=1)
            hi = local_to_epoch(datetime(nxt.year, nxt.month, nxt.day, 6), zone, 0)
            total += max(0, min(finish, hi) - max(begin, lo))
            day = nxt
        return total

    exceptions = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0,
                  "corrections_applied": applied}
    result = {}
    for emp, home in employees.items():
        items = sorted(by_employee.get(emp, []))
        kept = []
        for epoch, _rank, site, ident, direction in items:
            if kept and kept[-1][4] == direction and epoch - kept[-1][0] <= 300:
                rounded = shift_epoch(site, epoch)
                if start <= workday(home, rounded) <= end:
                    exceptions["duplicates_dropped"] += 1
                continue
            kept.append((epoch, 0, site, ident, direction))
        shifts = []
        pending = None
        for epoch, _rank, site, ident, direction in kept:
            rounded = shift_epoch(site, epoch)
            day = workday(home, rounded)
            in_period = start <= day <= end
            if direction == "IN":
                if pending and start <= pending[2] <= end:
                    exceptions["open_shifts"] += 1
                pending = (rounded, site, day)
            else:
                if pending and rounded - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], rounded, pending[1], pending[2]))
                    pending = None
                else:
                    if pending and start <= pending[2] <= end:
                        exceptions["open_shifts"] += 1
                    pending = None
                    if in_period:
                        exceptions["orphan_outs"] += 1
        if pending and start <= pending[2] <= end:
            exceptions["open_shifts"] += 1

        shifts = [shift for shift in shifts if start <= shift[3] <= end]
        shifts.sort(key=lambda shift: shift[0])
        day_used = {}
        week_used = {}
        count = paid_total = ot_total = night_total = 0
        gross = Fraction(0)
        for begin, finish, site, day in shifts:
            worked = max(0, (finish - begin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(site, begin, finish) // 60, paid)
            before = day_used.get(day, 0)
            day_used[day] = before + paid
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            normal = paid - daily_ot
            week = day - timedelta(days=day.weekday())
            wbefore = week_used.get(week, 0)
            week_used[week] = wbefore + normal
            weekly_ot = max(0, wbefore + normal - 2400) - max(0, wbefore - 2400)
            overtime = daily_ot + weekly_ot
            regular = paid - overtime
            rate = Fraction(0)
            for effective, value in rates.get(emp, []):
                if effective <= day:
                    rate = value
            gross += rate * (regular + Fraction(3, 2) * overtime) / 60 + rate * Fraction(15, 100) * night / 60
            count += 1
            paid_total += paid
            ot_total += overtime
            night_total += night
        cents = round_cents(gross)
        result[emp] = {"shifts": count, "paid_minutes": paid_total, "overtime_minutes": ot_total,
                       "night_minutes": night_total, "gross": "%d.%02d" % divmod(cents, 100)}

    totals = {key: sum(value[key] for value in result.values())
              for key in ("shifts", "paid_minutes", "overtime_minutes", "night_minutes")}
    cents = sum(int(value["gross"].replace(".", "")) for value in result.values())
    totals["gross"] = "%d.%02d" % divmod(cents, 100)
    output = {"period": {"start": period["start"], "end": period["end"]}, "employees": result,
              "exceptions": exceptions, "totals": totals}
    with open(out_file, "w") as handle:
        json.dump(output, handle, indent=1)


main()
